import{z as i,x as s,o as A,c as l,q as t,j as e,D as a,d as r,s as o,S as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"合规监控体系","description":"","frontmatter":{"title":"合规监控体系","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/qo-compliance-monitoring.md","filePath":"quant/qo-compliance-monitoring.md","lastUpdated":1791063341000}'),p={name:"quant/qo-compliance-monitoring.md"};function d(m,E,C,D,c,h){const n=s("Mermaid");return A(),l("div",null,[E[2]||(E[2]=t('<h1 id="合规监控体系" tabindex="-1">合规监控体系 <a class="header-anchor" href="#合规监控体系" aria-label="Permalink to &quot;合规监控体系&quot;">​</a></h1><div class="epigraph"><p>监控体系的价值不在抓到多少违规，而在让「仍在被允许的范围内」这句话，每天由数据说一遍。</p><footer>—— 据 MiFID II 第 17 条与 RTS 6 第 13 条、MAR 第 12 条口径整理</footer></div><p><a href="/quant/qo-vendor-channel">上一课</a>把外部依赖管成可测可退的对象；运营四课到此，机器每天正确运转。本课起转合规单元，回答另一个问题：运转是否仍在<strong>被允许的范围内</strong>。<a href="/quant/cn-compliance-map">合规红线与收束</a>把红线写成行为加数据的清单，<a href="/quant/mifid-ii-rts6">MiFID II RTS 6</a>写过操纵监测的公开要求——自动监测、告警、每年评估误报与漏报；本课写这套监测在机构内部的架构：对象、阈值、独立性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>红线清单是静态文本，交易是每秒都在发生的流；合规监控就是把流映射回清单的在线系统。缺口的形态有四：<strong>对象不全</strong>——只盯交易行为，漏掉通讯、员工账户、关联账户；<strong>独立性缺失</strong>——监控跑在策略系统里，误报被业务侧一点点调低，等于运动员兼裁判；<strong>阈值失养</strong>——市场节奏变了（波动率、参与率、撤单习惯），阈值还是三年前标的，监控失灵的形式不是狂响而是<strong>零告警</strong>；<strong>留痕断裂</strong>——告警处理没有记录，事后既无法自证也没有改进输入。这四条合起来是一个判断：监控体系是运营系统，不是合规部门的一摞制度文件。</p><p><span class="marginnote">直觉类比：红线清单是交规，合规监控是路口的摄像头——交规写在纸上不会自己抓违规；摄像头必须独立于司机、随车流变化调参数、每张罚单都有底片存档。少一样，整套体系就只剩威慑的姿态。</span></p>',6)),(A(),e(B,null,{default:a(()=>[o(n,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20G1%5B%22%E5%AF%B9%E8%B1%A1%E4%B8%8D%E5%85%A8%EF%BC%9A%E6%BC%8F%E6%8E%89%E9%80%9A%E8%AE%AF%E4%B8%8E%E5%91%98%E5%B7%A5%E8%B4%A6%E6%88%B7%22%5D%20--%3E%20SICK%5B%22%E7%9B%91%E6%8E%A7%E4%BD%93%E7%B3%BB%E5%A4%B1%E7%81%B5%22%5D%0A%20%20G2%5B%22%E7%8B%AC%E7%AB%8B%E6%80%A7%E7%BC%BA%E5%A4%B1%EF%BC%9A%E8%BF%90%E5%8A%A8%E5%91%98%E5%85%BC%E8%A3%81%E5%88%A4%22%5D%20--%3E%20SICK%0A%20%20G3%5B%22%E9%98%88%E5%80%BC%E5%A4%B1%E5%85%BB%EF%BC%9A%E5%A4%9A%E5%B9%B4%E6%9C%AA%E9%87%8D%E6%A0%A1%22%5D%20--%3E%20SICK%0A%20%20G4%5B%22%E7%95%99%E7%97%95%E6%96%AD%E8%A3%82%EF%BC%9A%E5%91%8A%E8%AD%A6%E5%A4%84%E7%90%86%E6%97%A0%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20SICK%0A%20%20SICK%20--%3E%20SIGN%5B%22%E5%A4%96%E5%9C%A8%E8%A1%A8%E7%8E%B0%E5%BE%80%E5%BE%80%E4%B8%8D%E6%98%AF%E7%8B%82%E5%93%8D%EF%BC%8C%E8%80%8C%E6%98%AF%E9%9B%B6%E5%91%8A%E8%AD%A6%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监控对象按红线清单展开，四类。<strong>交易行为</strong>：撤单率与申报节奏、自成交、价格逼近约束边时的排单行为、<a href="/quant/spoofing-layering">幌骗与分层</a>一类的模式特征；预防设计在下单引擎（禁自成交过滤、节奏控制），监测在其后独立复核。<strong>持仓与限额</strong>：敞口、集中度、<a href="/quant/rk-limit-system">限额体系</a>的逐档执行情况，越线即告警。<strong>信息与通讯</strong>：信息墙的越墙接触登记、受控通讯渠道之外的动作。<strong>人员与关联方</strong>：员工与关联账户的个人交易核对。架构上固定四层：规则引擎（独立部署、独立数据线）→ 告警分级 → 复核与升级（合规职能定级，业务职能答辩）→ 留痕与月度统计。阈值管理写成流程：每条规则记当前阈值、上次校准时间、当期误报率与漏报估计，按季重校。</p><p><span class="marginnote">数字实例：撤单率阈值不应写死「30%」。平静时段全市场撤单率可能只有 10%，开盘竞价附近可能冲到 50%——阈值应写成相对量，比如「自身近一季分布的 99% 分位」，并在市场波动率翻倍时自动触发重校提醒。</span></p>',3)),(A(),e(B,null,{default:a(()=>[o(n,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEED%5B%22%E8%AE%A2%E5%8D%95%E6%B5%81%20%2F%20%E6%8C%81%E4%BB%93%20%2F%20%E9%80%9A%E8%AE%AF%20%2F%20%E8%B4%A6%E6%88%B7%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20ENG%5B%22%E8%A7%84%E5%88%99%E5%BC%95%E6%93%8E%EF%BC%9A%E7%8B%AC%E7%AB%8B%E4%BA%8E%E7%AD%96%E7%95%A5%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20ENG%20--%3E%20GRADE%7B%22%E5%91%8A%E8%AD%A6%E5%88%86%E7%BA%A7%22%7D%0A%20%20GRADE%20--%3E%7C%22%E4%BD%8E%22%7C%20LOG%5B%22%E8%AE%B0%E5%BD%95%E4%B8%8E%E6%9C%88%E5%BA%A6%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20GRADE%20--%3E%7C%22%E9%AB%98%22%7C%20REV%5B%22%E5%90%88%E8%A7%84%E5%A4%8D%E6%A0%B8%EF%BC%8C%E4%B8%9A%E5%8A%A1%E7%AD%94%E8%BE%A9%22%5D%0A%20%20REV%20--%3E%7C%22%E8%AE%A4%E5%AE%9A%E5%8F%AF%E7%96%91%22%7C%20ESC%5B%22%E5%8D%87%E7%BA%A7%E5%A4%84%E7%BD%AE%EF%BC%8C%E5%BF%85%E8%A6%81%E6%97%B6%E4%B8%8A%E6%8A%A5%22%5D%0A%20%20REV%20--%3E%7C%22%E8%AF%AF%E6%8A%A5%22%7C%20TUNE%5B%22%E9%98%88%E5%80%BC%E8%AE%B0%E5%BD%95%E4%B8%8E%E5%AD%A3%E5%BA%A6%E9%87%8D%E6%A0%A1%22%5D%0A%20%20LOG%20--%3E%20TUNE%0A%20%20CAL%5B%22%E5%B9%B4%E5%BA%A6%E8%AF%84%E4%BC%B0%EF%BC%9A%E8%AF%AF%E6%8A%A5%E7%8E%87%E4%B8%8E%E6%BC%8F%E6%8A%A5%22%5D%20--%3E%20ENG%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>阈值选择的机制是误报与漏报的权衡，而这个权衡<strong>不该</strong>由业务侧单方决定：误报率 \\(\\Pr[\\text{告警}\\mid\\text{正常}]\\) 太高，复核通道瘫痪，真信号被淹没；漏报率的困难在于它不可直接观测——只能靠规则覆盖对标监管口径、靠抽检与情景回放来估计。<a href="/quant/mifid-ii-rts6">MiFID II RTS 6</a>把「每年评估误报与漏报」写成义务，机制理由正在这里：阈值不是法典，是与市场节奏共同漂移的参数，没有定期评估的监控必然走向零告警。为什么引擎必须独立：策略系统的第一目标是执行，监控的第一目标是质疑执行；两者共用一套数据可以，共用一套代码与一个负责人不行——这与<a href="/quant/sl-compliance-review">合规审查</a>里「合规门独立于判据」是同一条结构。为什么留痕是机制而非手续：告警处理记录是阈值重校的输入、是审计的证据、也是<a href="/quant/eu-ai-act-finance">EU AI Act 的金融条款</a>一类新规落到既有监控时的改造底图。</p><p><span class="marginnote">术语翻译：误报是「狼来了」——把正常交易当违规告出来；漏报是「真狼来了却没叫」。统计上它们是一对跷跷板：阈值调严误报少、漏报多，调松则相反。难点在漏报没法直接数——没人知道漏掉了多少，只能靠对标与回放去估。</span></p><p><span class="marginnote">监控失灵最常见的形式不是漏报大案，而是「本季度零告警」被当成好消息。健康指标是反向的：告警量骤降要先查阈值与数据线是否漂移，再谈市场变干净了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课是合规意识的工程化检查工具，不构成法律意见；认定标准、阈值与处罚尺度以当期法律法规与交易所、协会规则为准，口径同<a href="/quant/cn-compliance-map">合规红线与收束</a>。监测规则的细节不写成规避指南：讨论阈值校准是为了让体系有效，不是为了找出告警器的盲区——后者本身是操纵认定的从重情节。模型信号的模型风险治理不在本课，见 <a href="/quant/sr-11-7-model-risk">SR 11-7</a> 与 <a href="/quant/fml-audit">ML 审计</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>监控把静态红线清单映射到交易流上，对象四类：交易行为、持仓限额、信息通讯、人员关联方。</li><li>架构四层：独立规则引擎、告警分级、复核升级、留痕统计；引擎与策略系统分开部署、分开负责。</li><li>阈值是与市场节奏共同漂移的参数：误报率受控、漏报靠对标与回放估计，按季重校、按年评估。</li><li>「零告警」是失灵信号；告警处理留痕是重校、审计与新规改造的共同底座。</li><li>出处：据 MiFID II 第 17 条与 RTS 6 第 13 条、Regulation (EU) No 596/2014 第 12 条口径整理；红线清单见<a href="/quant/cn-compliance-map">合规红线与收束</a>。</li></ul>',8))])}const f=i(p,[["render",d]]);export{_ as __pageData,f as default};
